---------------- ONE TIME POPULATION SCRIPT FOR MAJORHWBUILDSDESIGNCONTACTS

INSERT INTO MAJORHWBUILDSDESIGNCONTACTS (DESIGNCONTACTID, MAJORHARDWAREBUILDSID,CREATIONUSER,MODIFICATIONUSER)  SELECT  DISTINCT UR.ID ,MH.MAJORHARDWAREID ,1 ,1 FROM SYSTEMTYPESMAJORHARDWAREBUILDS  STMHB JOIN SYSTEMTYPES ST ON ST.SYSTEMTYPEID = STMHB.SYSTEMTYPEID JOIN MAJORHARDWAREBUILDS MH ON MH.MAJORHARDWAREID = STMHB.MAJORHARDWAREID JOIN SYSTEMTYPESSUBDOMAINSPOC STSDMS ON STSDMS.SYSTEMTYPEID = ST.SYSTEMTYPEID  JOIN SUBDOMAINSPOCS SDMS ON SDMS.SUBDOMAINSPOCID = STSDMS.SUBDOMAINSPOCID JOIN  ASPNETUSERS UR ON UR.EMAIL = SDMS.SUBDOMAINSPOC  JOIN VERTICALRESPONSIBLES V ON  ST.VERTICALRESPONSIBLEID = V.VERTICALRESPONSIBLEID  JOIN ASPNETUSERROLES AUR ON AUR.USERID = UR.ID JOIN BUILDCONSTRUCTIONS BC ON BC.BUILDCONSTRUCTIONID = MH.BUILDCONSTRUCTIONID  WHERE BC.BUILDCONSTRUCTION NOT IN  ('BLUEPRINT NFVI', 'OTHER NFVI', 'BLUEPRINT NFCI', 'OTHER NFCI', 'VIRTUALISED'); 

Commit; 
 
 --SELECT  DISTINCT UR.ID ,MH.MAJORHARDWAREID ,1 ,1 FROM SYSTEMTYPESMAJORHARDWAREBUILDS  STMHB JOIN SYSTEMTYPES ST ON ST.SYSTEMTYPEID = STMHB.SYSTEMTYPEID JOIN MAJORHARDWAREBUILDS MH ON MH.MAJORHARDWAREID = STMHB.MAJORHARDWAREID JOIN SYSTEMTYPESSUBDOMAINSPOC STSDMS ON STSDMS.SYSTEMTYPEID = ST.SYSTEMTYPEID  JOIN SUBDOMAINSPOCS SDMS ON SDMS.SUBDOMAINSPOCID = STSDMS.SUBDOMAINSPOCID JOIN  ASPNETUSERS UR ON UR.EMAIL = SDMS.SUBDOMAINSPOC  JOIN VERTICALRESPONSIBLES V ON  ST.VERTICALRESPONSIBLEID = V.VERTICALRESPONSIBLEID  JOIN ASPNETUSERROLES AUR ON AUR.USERID = UR.ID JOIN BUILDCONSTRUCTIONS BC ON BC.BUILDCONSTRUCTIONID = MH.BUILDCONSTRUCTIONID  WHERE BC.BUILDCONSTRUCTION NOT IN  ('BLUEPRINT NFVI', 'OTHER NFVI', 'BLUEPRINT NFCI', 'OTHER NFCI', 'VIRTUALISED'); 
